def get_available_slots(self, date):
    """
    Get all available time slots on a given date.
    :param date: The date to get available time slots for,datetime.
    :return: A list of available time slots on the given date,list.
    """
    slots = []
    events = sorted([event for event in self.events if event['date'].date() == date.date()], key=lambda x: x['start_time'])
    if not events:
        return [(datetime.combine(date.date(), datetime.min.time()), datetime.combine(date.date(), datetime.max.time()))]
    else:
        if events[0]['start_time'].time() != datetime.min.time():
            slots.append((datetime.combine(date.date(), datetime.min.time()), events[0]['start_time']))
        for i in range(len(events) - 1):
            slots.append((events[i]['end_time'], events[i + 1]['start_time']))
        if events[-1]['end_time'].time() != datetime.max.time():
            slots.append((events[-1]['end_time'], datetime.combine(date.date(), datetime.max.time())))
    return slots

