    from scipy.interpolate import interp2d

    f = interp2d(x, y, z, kind='linear')
    z_interp = []

    for xi, yi in zip(x_interp, y_interp):
        zi = f(xi, yi)
        z_interp.append(zi[0])

    return z_interp

@staticmethod
def interpolate_2d(x, y, z, x_interp, y_interp):
    z_interp = []
    for xi, yi in zip(x_interp, y_interp):
        if xi in x and yi in y:
            i = x.index(xi)
            j = y.index(yi)
            z_interp.append(z[i][j])
        else:
            i = 0
            while xi > x[i]:
                i += 1
            j = 0
            while yi > y[j]:
                j += 1
            x1, x2 = x[i-1], x[i]
            y1, y2 = y[j-1], y[j]
            z11, z12 = z[i-1][j-1], z[i-1][j]
            z21, z22 = z[i][j-1], z[i][j]
            zi = z11 + ((z21 - z11) / (x2 - x1)) * (xi - x1) + ((z12 - z11) / (y2 - y1)) * (yi - y1)
            z_interp.append(zi)
    return z_interp

def interpolate_1d(self, x, y, x_interp):
